import {
  type Announcements,
  DndContext,
  type DragEndEvent,
  DragOverlay,
  KeyboardSensor,
  type Modifier,
  MouseSensor,
  TouchSensor,
  type UniqueIdentifier,
  closestCenter,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import {
  SortableContext,
  sortableKeyboardCoordinates,
  useSortable,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { type ReactNode, useState } from "react";
import { moveFor } from "../../lib/task-list.ts";
import { Icon } from "./icon.tsx";

/** Anything the list can order: it only needs a stable string id. */
export interface Sortable {
  readonly id: string;
}

/** Props for `SortableList`. */
export interface SortableListProps<T extends Sortable> {
  readonly items: readonly T[];
  readonly label: string;
  readonly itemLabel: (item: T) => string;
  readonly onMove: (id: string, afterId: string | null) => void;
  readonly children: (item: T, handle: ReactNode) => ReactNode;
  readonly disabled?: boolean;
  readonly className?: string;
  readonly itemClassName?: string;
}

/** A row while it is carried: lifted off the page on the shade token. */
export const liftedClass = "cursor-grabbing bg-sheet shadow-lifted";

/** The row's place while it is carried, which is where it will drop: an empty dashed slot. */
export const dropSlotClass =
  "bg-rule/20 outline-2 -outline-offset-4 outline-rule-strong outline-dashed [&>*]:invisible";

const handleClass =
  "flex size-touch shrink-0 cursor-grab touch-none items-center justify-center text-ink-muted transition-colors hover:text-ink active:cursor-grabbing";

/** The look of a drag handle without its behaviour, for the lifted copy of a row. */
export function DragHandleMark() {
  return (
    <span aria-hidden="true" className={handleClass}>
      <Icon name="grip" />
    </span>
  );
}

const verticalOnly: Modifier = ({ transform }) => ({ ...transform, x: 0 });

const instructions = {
  draggable:
    "To move an item, press Space or Enter on its handle. Use the up and down arrow keys to move it, then press Space or Enter to drop it, or Escape to cancel.",
};

const announcementsFor = (
  ids: readonly string[],
  nameOf: (id: UniqueIdentifier) => string,
): Announcements => {
  const at = (id: UniqueIdentifier) =>
    `position ${String(ids.indexOf(String(id)) + 1)} of ${String(ids.length)}`;
  return {
    onDragStart: ({ active }) => `Picked up ${nameOf(active.id)}, at ${at(active.id)}.`,
    onDragOver: ({ active, over }) =>
      over
        ? `${nameOf(active.id)} is now at ${at(over.id)}.`
        : `${nameOf(active.id)} is outside the list.`,
    onDragEnd: ({ active, over }) =>
      over ? `Dropped ${nameOf(active.id)} at ${at(over.id)}.` : `Dropped ${nameOf(active.id)}.`,
    onDragCancel: ({ active }) =>
      `Move cancelled. ${nameOf(active.id)} is back at ${at(active.id)}.`,
  };
};

/**
 * A list the user reorders by mouse, touch (press and hold the handle) or keyboard.
 * It reports each move as `onMove(id, afterId)`, with `afterId` null for the top, and leaves the order to its owner.
 */
export function SortableList<T extends Sortable>({
  items,
  label,
  itemLabel,
  onMove,
  children,
  disabled = false,
  className = "",
  itemClassName = "",
}: SortableListProps<T>) {
  const sensors = useSensors(
    useSensor(MouseSensor, { activationConstraint: { distance: 4 } }),
    useSensor(TouchSensor, { activationConstraint: { delay: 150, tolerance: 6 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  );
  const ids = items.map((item) => item.id);
  const byId = new Map(items.map((item) => [item.id, item]));
  const nameOf = (id: UniqueIdentifier) => {
    const item = byId.get(String(id));
    return item ? itemLabel(item) : "item";
  };
  const [carried, setCarried] = useState<T | null>(null);
  const handleDragEnd = ({ active, over }: DragEndEvent) => {
    setCarried(null);
    const move = over ? moveFor(ids, String(active.id), String(over.id)) : null;
    if (move) onMove(move.taskId, move.afterId);
  };

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      modifiers={[verticalOnly]}
      accessibility={{
        announcements: announcementsFor(ids, nameOf),
        screenReaderInstructions: instructions,
      }}
      onDragStart={({ active }) => {
        setCarried(byId.get(String(active.id)) ?? null);
      }}
      onDragCancel={() => {
        setCarried(null);
      }}
      onDragEnd={handleDragEnd}
    >
      <SortableContext items={ids} strategy={verticalListSortingStrategy} disabled={disabled}>
        <ul aria-label={label} className={className}>
          {items.map((item) => (
            <SortableItem
              key={item.id}
              item={item}
              name={itemLabel(item)}
              disabled={disabled}
              className={itemClassName}
              render={children}
            />
          ))}
        </ul>
      </SortableContext>
      <DragOverlay dropAnimation={null}>
        {carried && (
          <div aria-hidden="true" inert className={`${itemClassName} ${liftedClass}`}>
            {children(carried, <DragHandleMark />)}
          </div>
        )}
      </DragOverlay>
    </DndContext>
  );
}

interface SortableItemProps<T extends Sortable> {
  readonly item: T;
  readonly name: string;
  readonly disabled: boolean;
  readonly className: string;
  readonly render: (item: T, handle: ReactNode) => ReactNode;
}

function SortableItem<T extends Sortable>({
  item,
  name,
  disabled,
  className,
  render,
}: SortableItemProps<T>) {
  const {
    attributes,
    listeners,
    setNodeRef,
    setActivatorNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: item.id, disabled });
  const handle = disabled ? null : (
    <button
      type="button"
      ref={setActivatorNodeRef}
      {...attributes}
      {...listeners}
      aria-label={`Move ${name}`}
      className={handleClass}
    >
      <Icon name="grip" />
    </button>
  );
  return (
    <li
      ref={setNodeRef}
      style={{
        transform: CSS.Translate.toString(transform),
        transition: transition ? "transform var(--duration-base) var(--ease-standard)" : undefined,
      }}
      className={`${className} ${isDragging ? dropSlotClass : ""}`}
    >
      {render(item, handle)}
    </li>
  );
}
import type { ReactNode } from "react";
import { type DueTone, dueLabel } from "../../lib/due-date.ts";
import { routes } from "../../lib/routes.ts";
import type { Task } from "../../lib/schema/task.ts";
import { Checkbox } from "./checkbox.tsx";
import { Link } from "./link.tsx";

const columns = {
  reorderable:
    "grid-cols-[var(--spacing-touch)_minmax(0,1fr)_var(--spacing-touch)] @wide:grid-cols-[var(--spacing-touch)_var(--spacing-touch)_minmax(0,1fr)_var(--container-due)]",
  fixed:
    "grid-cols-[var(--spacing-touch)_minmax(0,1fr)] @wide:grid-cols-[var(--spacing-touch)_minmax(0,1fr)_var(--container-due)]",
} as const;

/**
 * One ruled ledger line. Narrow: tick box, text, then the handle at the right edge. Wide: handle, tick box, text,
 * then the due column. Without a handle the handle column is dropped.
 */
export const ledgerLineClass = (reorderable: boolean): string =>
  `grid items-start border-b border-rule last:border-b-0 ${reorderable ? columns.reorderable : columns.fixed}`;

/** A ledger line the user works with: it shades on hover and while something in it has keyboard focus. */
export const taskLineClass = (reorderable: boolean): string =>
  `${ledgerLineClass(reorderable)} transition-colors hover:bg-rule/25 has-focus-visible:bg-rule/25`;

/** The colour and weight of a due date in each tone, shared by the list and the detail screen. */
export const dueToneClass: Readonly<Record<DueTone, string>> = {
  alert: "font-medium text-alert",
  emphasis: "font-medium text-ink",
  quiet: "text-ink-muted",
};

/** Props for `LedgerCells`. */
export interface LedgerCellsProps {
  /** The drag handle, or a falsy value when the line has no handle column. */
  readonly handle: ReactNode;
  readonly control: ReactNode;
  readonly children: ReactNode;
  readonly due?: ReactNode;
}

/**
 * The cells of one ledger line: tick box, the text right of the red double margin rule, the due date (under the
 * title when narrow, in its own ruled column when wide) and the handle. Real, pending and placeholder lines all use
 * it, so they align.
 */
export function LedgerCells({ handle, control, children, due }: LedgerCellsProps) {
  return (
    <>
      {handle && <span className="order-last @wide:order-first @wide:py-1">{handle}</span>}
      <span className="flex size-touch items-center justify-center @wide:box-content @wide:py-1">
        {control}
      </span>
      <div className="relative flex min-w-0 flex-col gap-1 border-l-3 border-double border-margin py-2 pr-1 pl-3 @wide:contents">
        <div className="flex min-w-0 flex-col gap-1 @wide:relative @wide:border-l-3 @wide:border-double @wide:border-margin @wide:px-4 @wide:py-3">
          {children}
        </div>
        <p className="text-caption tabular-nums empty:hidden @wide:block @wide:self-stretch @wide:border-l @wide:border-margin/40 @wide:px-4 @wide:pt-4 @wide:pb-3 @wide:text-right @wide:empty:block">
          {due}
        </p>
      </div>
    </>
  );
}

/** Props for `LedgerHead`. */
export interface LedgerHeadProps {
  readonly reorderable: boolean;
}

/** The ledger's column headings, shown on wide screens only and hidden from screen readers. */
export function LedgerHead({ reorderable }: LedgerHeadProps) {
  return (
    <div
      aria-hidden="true"
      className={`hidden border-b border-rule-strong text-caption font-medium tracking-caps text-ink-muted uppercase @wide:grid ${reorderable ? columns.reorderable : columns.fixed}`}
    >
      <span className={reorderable ? "col-span-2" : undefined} />
      <span className="border-l-3 border-double border-margin px-4 pt-3 pb-2">Task</span>
      <span className="border-l border-margin/40 px-4 pt-3 pb-2 text-right">Due</span>
    </div>
  );
}

/** Props for `TaskRow`. */
export interface TaskRowProps {
