import { useNavigate, useParams } from "react-router";
import { type ApiError, ApiErrorCode } from "../lib/api/client.ts";
import { localIsoDate } from "../lib/due-date.ts";
import { useDeleteTask, useTask, useToggleTask, useUpdateTask } from "../lib/query/tasks.ts";
import { routes } from "../lib/routes.ts";
import { serverFieldErrors } from "../lib/schema/field-errors.ts";
import { taskIdParamSchema } from "../lib/schema/route.ts";
import type { Task } from "../lib/schema/task.ts";
import { draftFields } from "../lib/task-draft.ts";
import { type TaskDetailContent, TaskDetailView } from "../views/task-detail-view.tsx";

const detailContent = (
  taskId: string | null,
  task: Task | undefined,
  error: ApiError | null,
): TaskDetailContent => {
  if (taskId === null || error?.code === ApiErrorCode.NotFound) return { status: "not-found" };
  if (task) return { status: "ready", task };
  return { status: "loading" };
};

// A 412 shows as "Changed elsewhere" and a field problem shows next to its field, so neither needs a second message.
const saveFailure = (error: ApiError | null): string | null => {
  if (error === null) return null;
  if (error.code === ApiErrorCode.VersionMismatch || error.code === ApiErrorCode.ValidationFailed)
    return null;
  return `Couldn't save the task. ${error.message}`;
};

const toggleFailure = (error: ApiError | null): string | null =>
  error && `Couldn't update the task, so it's back as it was. ${error.message}`;

/** The task detail route: one task to read, tick off, edit with `If-Match`, or delete. */
export function TaskDetailPage() {
  const params = useParams();
  const parsedId = taskIdParamSchema.safeParse(params.taskId);
  const taskId = parsedId.success ? parsedId.data : null;
  const task = useTask(taskId);
  const update = useUpdateTask();
  const toggle = useToggleTask();
  const remove = useDeleteTask();
  const navigate = useNavigate();

  return (
    <TaskDetailView
      content={detailContent(taskId, task.data, task.error)}
      today={localIsoDate(new Date())}
      saving={update.isPending}
      deleting={remove.isPending}
      failure={saveFailure(update.error) ?? toggleFailure(toggle.error)}
      fieldErrors={
        update.error?.code === ApiErrorCode.ValidationFailed
          ? serverFieldErrors(update.error.details, draftFields)
          : undefined
      }
      onSave={(id, changes, version) => {
        update.mutate({ taskId: id, changes, version });
      }}
      onToggle={(id, completed) => {
        toggle.mutate({ taskId: id, completed });
      }}
      onDelete={(id) => {
        remove.mutate(id);
        void navigate(routes.tasks);
      }}
    />
  );
}
import type { Task } from "./schema/task.ts";

/** Open and completed counts for a list of tasks. */
export interface TaskSummary {
  readonly open: number;
  readonly done: number;
}

/** A reorder as the API takes it: put `taskId` right after `afterId`, or at the top when null. */
export interface Move {
  readonly taskId: string;
  readonly afterId: string | null;
}

/** Count open and completed tasks. */
export const summarize = (tasks: readonly Task[]): TaskSummary =>
  tasks.reduce<TaskSummary>(
    (counts, task) =>
      task.completed ? { ...counts, done: counts.done + 1 } : { ...counts, open: counts.open + 1 },
    { open: 0, done: 0 },
  );

/** True when the search box holds a term. Reordering is off while searching, since moving within a filtered list is ambiguous. */
export const isSearching = (query: string): boolean => query.trim() !== "";

/** The one line under the list heading: counts, matches, or that a search is running. */
export const listSummary = (
  tasks: readonly Task[],
  query: string,
  searchPending: boolean,
): string => {
  if (searchPending) return "Searching…";
  if (!isSearching(query)) {
    const { open, done } = summarize(tasks);
    return `${String(open)} open · ${String(done)} done`;
  }
  if (tasks.length === 0) return "No matches.";
  const noun = tasks.length === 1 ? "match" : "matches";
  return `${String(tasks.length)} ${noun} for “${query.trim()}”. Reordering is off while you search.`;
};

/** Turn a drop of `activeId` onto `overId`'s place into the move the API expects, or null for no change. */
export const moveFor = (ids: readonly string[], activeId: string, overId: string): Move | null => {
  const from = ids.indexOf(activeId);
  const to = ids.indexOf(overId);
  if (from === -1 || to === -1 || from === to) return null;
  const reordered = ids.toSpliced(from, 1).toSpliced(to, 0, activeId);
  return { taskId: activeId, afterId: reordered[to - 1] ?? null };
};
import { z } from "zod";

/** A task title as the user types it: trimmed, 1 to 200 characters. */
export const titleSchema = z
  .string()
  .trim()
  .min(1, "Add a title.")
  .max(200, "Keep the title to 200 characters.");

/** Task notes: free text up to 5,000 characters, empty when there are none. */
export const notesSchema = z.string().max(5000, "Keep the notes to 5,000 characters.");

/** One task as the API sends it (camelCase on the wire). */
export const taskSchema = z.object({
  id: z.uuid(),
  title: titleSchema,
  notes: notesSchema,
  completed: z.boolean(),
  dueDate: z.iso.date().nullable(),
  rank: z.string(),
  version: z.int().positive(),
