import { useState } from "react";
import { useDebouncedValue } from "../hooks/use-debounced-value.ts";
import { localIsoDate } from "../lib/due-date.ts";
import type { ApiError } from "../lib/api/client.ts";
import {
  useCreateTask,
  useMoveTask,
  usePendingDeletes,
  useTaskNotices,
  useTasks,
  useToggleTask,
} from "../lib/query/tasks.ts";
import type { Task } from "../lib/schema/task.ts";
import { type TaskListContent, TaskListView } from "../views/task-list-view.tsx";

const searchDelayMs = 250;

// Tasks already on screen stay there through a failed refetch; the error screen is only for a first load that failed.
const listContent = (
  tasks: readonly Task[] | undefined,
  error: ApiError | null,
): TaskListContent => {
  if (tasks) return { status: "ready", tasks };
  if (error) return { status: "error", message: error.message };
  return { status: "loading" };
};

/** The task list route: the user's tasks, searched on the server as they type, ticked off, reordered and added to. */
export function TaskListPage() {
  const [query, setQuery] = useState("");
  const term = useDebouncedValue(query.trim(), searchDelayMs);
  const list = useTasks(term);
  const deleting = usePendingDeletes();
  const create = useCreateTask();
  const toggle = useToggleTask();
  const move = useMoveTask();
  const { notice, dismiss } = useTaskNotices();

  return (
    <TaskListView
      content={listContent(
        list.data?.filter((task) => !deleting.has(task.id)),
        list.error,
      )}
      today={localIsoDate(new Date())}
      query={query}
      searchPending={query.trim() !== term || list.isPlaceholderData}
      pendingCreate={create.isPending ? create.variables.title : null}
      failure={notice === null ? null : { message: notice }}
      onQueryChange={setQuery}
      onCreate={(title) => {
        create.mutate({ title });
      }}
      onToggle={(taskId, completed) => {
        toggle.mutate({ taskId, completed });
      }}
      onMove={(taskId, afterId) => {
        move.mutate({ taskId, afterId });
      }}
      onRetry={() => {
        void list.refetch();
      }}
      onDismissFailure={dismiss}
    />
  );
}
import { Navigate, useSearchParams } from "react-router";
import { ApiErrorCode, type ApiError } from "../lib/api/client.ts";
import { useAuth } from "../lib/auth/auth-context.tsx";
import { serverFieldErrors } from "../lib/schema/field-errors.ts";
import { returnToSchema } from "../lib/schema/route.ts";
import { type SignUpFailure, SignUpView } from "../views/sign-up-view.tsx";

const credentialFields = ["email", "password"] as const;

// A field problem shows next to its field; any failure other than a taken email means the server couldn't help.
const failureOf = (error: ApiError | null): SignUpFailure | null => {
  if (error === null || error.code === ApiErrorCode.ValidationFailed) return null;
  return error.code === ApiErrorCode.EmailTaken ? "email-taken" : "unreachable";
};

/** The sign-up route: creates the account, which signs the user in, then goes where sign-in would have. */
export function SignUpPage() {
  const { status, signUp } = useAuth();
  const [searchParams] = useSearchParams();
  const returnTo = returnToSchema.parse(searchParams.get("returnTo"));

  if (status === "signed-in") return <Navigate to={returnTo} replace />;
  return (
    <SignUpView
      submitting={signUp.isPending}
      failure={failureOf(signUp.error)}
      fieldErrors={
        signUp.error?.code === ApiErrorCode.ValidationFailed
          ? serverFieldErrors(signUp.error.details, credentialFields)
          : undefined
      }
      onSubmit={(credentials) => {
        signUp.mutate(credentials);
      }}
    />
  );
}
import type { ComponentProps } from "react";
import { Field, fieldClass } from "./field.tsx";

/** Props for `TextField`: a native input plus its label, hint and error. */
export interface TextFieldProps extends Omit<ComponentProps<"input">, "id" | "className"> {
  readonly label: string;
  readonly hideLabel?: boolean;
  readonly hint?: string | undefined;
  readonly error?: string | undefined;
  readonly className?: string;
}

/** A labelled single-line input that shows its hint and error underneath. */
export function TextField({ label, hideLabel, hint, error, className, ...props }: TextFieldProps) {
  return (
    <Field label={label} hideLabel={hideLabel} hint={hint} error={error} className={className}>
      {(control) => <input {...control} className={fieldClass} {...props} />}
    </Field>
  );
}
