const sizes = {
  band: "border-y-3 py-1 text-lead",
  cover: "border-y-4 py-3 text-display @wide:text-cover",
} as const;

/** Props for `LedgerTitle`. */
export interface LedgerTitleProps {
  readonly size: keyof typeof sizes;
}

/** The app's name tooled in gilt between double rules, the way a ledger's title sits on its spine and cover. */
export function LedgerTitle({ size }: LedgerTitleProps) {
  return (
    <span
      className={`inline-block border-double border-gilt font-display font-medium tracking-caps text-gilt uppercase ${sizes[size]}`}
    >
      To Do
    </span>
  );
}
import { type ReactNode, useId } from "react";
import { LedgerTitle } from "./ui/ledger-title.tsx";

/** Props for `AuthLayout`. */
export interface AuthLayoutProps {
  readonly title: string;
  readonly children: ReactNode;
  readonly footer: ReactNode;
}

/**
 * The ledger opened at its title page: the cloth cover with the title tooled in gilt inside a blind-stamped double
 * frame, and beside it (below it on a phone) the first page, which holds the form.
 */
export function AuthLayout({ title, children, footer }: AuthLayoutProps) {
  const headingId = useId();
  return (
    <div className="@container flex min-h-dvh items-center bg-binding text-on-binding">
      <div className="mx-auto grid w-full max-w-book gap-6 px-4 py-6 @wide:grid-cols-2 @wide:gap-12 @wide:px-8 @wide:py-16">
        <div className="flex flex-col items-center justify-center gap-4 border-3 border-double border-gilt/60 px-6 py-8 text-center @wide:aspect-3/4 @wide:gap-6 @wide:py-16">
          <LedgerTitle size="cover" />
          <span aria-hidden="true" className="h-px w-12 bg-gilt/60" />
          <p className="text-caption font-medium tracking-caps text-balance uppercase">
            A ledger for the things you mean to do
          </p>
        </div>
        <article
          aria-labelledby={headingId}
          className="flex flex-col gap-6 rounded-sheet bg-sheet px-6 py-8 text-ink shadow-sheet @wide:justify-center @wide:px-12 @wide:py-12"
        >
          <h1 id={headingId} className="font-display text-title font-medium text-balance">
            {title}
          </h1>
          {children}
          <p className="text-ink-muted">{footer}</p>
        </article>
      </div>
    </div>
  );
}
import { type ReactNode, useId } from "react";

/** The look every text control shares: inputs, the search box and text areas. */
export const fieldClass =
  "min-h-touch w-full rounded-control border border-rule-strong bg-sheet px-3 text-ink transition-colors placeholder:text-ink-muted hover:border-ink aria-invalid:border-alert disabled:opacity-60";

/** What `Field` hands its control so the label, hint and error are wired to it. */
export interface FieldControlProps {
  readonly id: string;
  readonly "aria-invalid": true | undefined;
  readonly "aria-describedby": string | undefined;
}

/** Props for `Field`. */
export interface FieldProps {
  readonly label: string;
  readonly hideLabel?: boolean | undefined;
  readonly hint?: string | undefined;
  readonly error?: string | undefined;
  readonly className?: string | undefined;
  readonly children: (control: FieldControlProps) => ReactNode;
}

/** A label, a control, a hint and an error, linked so a screen reader reads them together. */
export function Field({
  label,
  hideLabel = false,
  hint,
  error,
  className = "",
  children,
}: FieldProps) {
  const id = useId();
  const hintId = hint ? `${id}-hint` : undefined;
  const errorId = error ? `${id}-error` : undefined;
  const describedBy = [hintId, errorId].filter(Boolean).join(" ") || undefined;
  return (
    <div className={`flex flex-col gap-1 ${className}`}>
      <label htmlFor={id} className={hideLabel ? "sr-only" : "text-caption font-medium text-ink"}>
        {label}
      </label>
      {children({ id, "aria-invalid": error ? true : undefined, "aria-describedby": describedBy })}
      {hint && (
        <p id={hintId} className="text-caption text-ink-muted">
          {hint}
        </p>
      )}
      {error && (
        <p id={errorId} className="text-caption text-alert">
          {error}
        </p>
      )}
    </div>
  );
}

